SELECT DATE_FORMAT(s.opened_date, 'yyyy-MM') AS opened_month, COUNT(DISTINCT o.amount) AS unique_channels, SORT_ARRAY(COLLECT_SET(o.status)) AS status_list FROM orders o INNER JOIN customers c ON c.id = o.customer_id INNER JOIN stores s ON s.id = o.store_id WHERE o.channel IN ('store', 'mobile') GROUP BY DATE_FORMAT(s.opened_date, 'yyyy-MM') HAVING COUNT(DISTINCT o.amount) >= 2 ORDER BY opened_month LIMIT 20
